SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, MAX(humidity) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS humidity_max_1h, AVG(humidity) OVER (PARTITION BY device_code) AS device_code_avg_humidity, DENSE_RANK() OVER (PARTITION BY device_code ORDER BY status_bits DESC) AS status_bits_dense_rank FROM device_readings;
